/* ---------- 틀 풀기 ---------- */
function b64dec(s){ const A="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"; const map=new Int16Array(128).fill(-1); for(let i=0;i<64;i++) map[A.charCodeAt(i)]=i;
  let n=0; for(let i=0;i<s.length;i++){ const c=s.charCodeAt(i); if(c<128&&map[c]>=0) n++; } const out=new Uint8Array((n*6)>>3); let buf=0,bits=0,o=0;
  for(let i=0;i<s.length;i++){ const c=s.charCodeAt(i); const v=c<128?map[c]:-1; if(v<0) continue; buf=((buf<<6)|v)&0xffffff; bits+=6; if(bits>=8){ bits-=8; out[o++]=(buf>>bits)&255; } } return out; }
let T=null, TX=null, USE_X=false;   // USE_X: 반대 극성(GMS 꼴) 읽기 동안만 추가 틀(명조·고정폭)까지
const TGT="0123456789./nmµuAÅ-⁻¹p";
function tpl(){ if(USE_X&&typeof TPL_B64_X!=="undefined"&&TPL_B64_X){ if(!TX){ const a=b64dec(TPL_B64), x=b64dec(TPL_B64_X); const c=new Uint8Array(a.length+x.length); c.set(a,0); c.set(x,a.length); TX=build(c); } return TX; }
  if(T) return T; T=build(b64dec(TPL_B64)); return T; }
function build(b){ const R=32, n=Math.floor(b.length/R); const cls=new Uint8Array(n), on=[], la=new Float32Array(n), rh=new Float32Array(n), rb=new Float32Array(n), ho=new Uint8Array(n);
  for(let k=0;k<n;k++){ const o=k*R; cls[k]=b[o]; const idx=[]; for(let i=0;i<NB;i++) if((b[o+1+(i>>3)]>>(7-(i&7)))&1) idx.push(i); on.push(Uint8Array.from(idx)); la[k]=b[o+28]/40-4; rh[k]=b[o+29]/100; rb[k]=b[o+30]/100-1; ho[k]=b[o+31]; }
  const classes=Array.from(TPL_CLASSES); const ci={}; classes.forEach((c,i)=>{ ci[c]=i; });
  return {n,cls,on,la,rh,rb,ho,classes,ci,nc:classes.length,tgt:Array.from(TGT).map(c=>ci[c]).filter(x=>x!=null)}; }

