  const rg=mx-mn, out=[]; if(!FB||FB.n<w*h) FB={n:w*h,lab:new Int32Array(w*h),st:new Int32Array(w*h),M:new Uint8Array(w*h)}; // 큰 버퍼는 다시 씀
  const lab=FB.lab.subarray(0,w*h), st=FB.st, M=FB.M;
