      let by0=-1, by1=-1, best=0; const blocks=[]; for(let i=0;i<rows.length;){ if(rows[i]<minFill*bw){ i++; continue; } let j=i; while(j+1<rows.length&&rows[j+1]>=minFill*bw) j++; blocks.push([i,j]); if(j-i+1>best){ best=j-i+1; by0=y0+i; by1=y0+j; } i=j+1; }
      let hollow=false, fr=0, bx0=x0, bx1=x1;
