      if(by0<0||best>Math.max(12,bw/3.5)||frame){ // 속 빈 테두리? (위·아래 줄, 왼·오른 열이 꽉 참)
        const bh=y1-y0+1; if(!bright||bh<5||bh>Math.max(40,bw/3)) continue; let top=0,bot=0,lft=0,rgt=0; for(let x=x0;x<=x1;x++){ if(lab[y0*w+x]===me) top++; if(lab[y1*w+x]===me) bot++; } for(let y=y0;y<=y1;y++){ if(lab[y*w+x0]===me) lft++; if(lab[y*w+x1]===me) rgt++; }
        if(Math.min(top,bot)<0.9*bw||Math.min(lft,rgt)<0.9*bh){ if(frame&&by0>=0&&best<=Math.max(12,bw/3.5)){ /* 테두리 아님 → 가장 두꺼운 행 덩어리 */ } else continue; }
        else { while(fr<bw/2&&lab[((y0+y1)>>1)*w+x0+fr]===me) fr++; hollow=true; by0=y0; by1=y1; } }
      if(!hollow){
        // 막대 행 안의 실제 가로 범위
        let a=x1, b=x0; for(let y=by0;y<=by1;y++) for(let x=x0;x<=x1;x++) if(lab[y*w+x]===me){ if(x<a) a=x; if(x>b) b=x; } bx0=a; bx1=b; }
      const yA=by0, yB=by1, xA=bx0, xB=bx1, BW=xB-xA+1; if(yB-yA<1&&!hollow) continue; // 1 px 선(글자 획)은 아님
      // 위아래 둘레가 반대 극성이어야 (흐림 고려 3 px 밖)
      const side=y=>{ if(y<0||y>=h) return NaN; const v=[]; for(let x=xA;x<=xB;x+=2) v.push(img[y*w+x]); return median(v); }; const cval=bright?mx:mn;
