      const off=2; const c1=Math.abs(side(yA-off)-cval)||0, c2=Math.abs(side(yB+off)-cval)||0;
      if(!(Math.max(c1,c2)>=0.5*rg&&Math.min(c1,c2)>=0.3*rg)) continue;
